+              info: { name: "Health Check", type: "http", seq: 1 },
+              http: {
+                method: "GET",
+                url: "{{baseUrl}}/health",
+              },
+            },
+          },
+        ],
+      },
+    ],
+  };
+
+  await writeCollection(collection);
+  options.output.success(`Initialized collection in ${dir}`);
+}

