+        },
+      },
+    },
+    items: [
+      {
+        kind: "folder",
+        name: "Root",
+        path: "root",
+        children: [
+          {
+            kind: "request",
+            name: "First",
+            path: "root/first.yml",
+            seq: 1,
+            request: {
+              info: { name: "First", type: "http", seq: 1 },
+              http: { method: "GET", url: "{{baseUrl}}/{{apiVersion}}/first" },
+            },
+          },
+          {
+            kind: "request",
+            name: "Second",
+            path: "root/second.yml",
+            seq: 2,
+            request: {
+              info: { name: "Second", type: "http", seq: 2 },
+              http: {
+                method: "GET",
