+              http: { method: "GET", url: "{{baseUrl}}/third" },
+            },
+          },
+        ],
+      },
+    ],
+  };
+}
+
+function response(status = 200, body = "{}", duration = 1): HttpClientResponse {
+  return {
+    status,
+    headers: { "content-type": "application/json" },
+    body,
+    size: Buffer.byteLength(body, "utf8"),
+    duration,
+  };
+}
