+
+import type {
+  AuthConfig,
+  IntrospectOptions,
+} from "@apifn/core";
+
+// ============================================================================
+// Collection Types
+// ============================================================================
+
+export interface Collection {
+  /** Collection metadata from opencollection.yml */
+  info: CollectionInfo;
+  /** Environments */
+  environments: Record<string, Environment>;
+  /** Request items organized by folder */
+  items: CollectionItem[];
+  /** Root directory path */
+  rootDir: string;
+}
+
+export interface CollectionInfo {
+  name: string;
+  version?: string;
+  description?: string;
+  type?: "collection";
+}
+
+export interface CollectionItem {
+  kind: "request" | "folder";
+  name: string;
+  /** Relative path within the collection */
+  path: string;
+  /** For kind: "request" — the parsed OpenCollection request YAML */
+  request?: OpenCollectionRequest;
+  /** For kind: "folder" — child items */
+  children?: CollectionItem[];
+  /** Sequence number for ordering */
+  seq?: number;
