+    params?: {
+      path?: Array<{ name: string; value: string }>;
+      query?: Array<{ name: string; value: string; enabled?: boolean }>;
+    };
+  };
+  runtime?: {
+    scripts?: Array<{
+      type: "pre-request" | "tests" | "post-response";
+      code: string;
+    }>;
+  };
+  settings?: {
+    encodeUrl?: boolean;
+    timeout?: number;
+    followRedirects?: boolean;
+    maxRedirects?: number;
+    expectedStatus?: number | number[];
+  };
+}
+
+// ============================================================================
+// Environment Types
+// ============================================================================
+
