+export async function fetchEndpointMetrics(
+    options: FetchEndpointMetricsOptions
+): Promise<EndpointMetrics[]> {
+    const {
+        baseUrl,
+        timeRange,
+        endpoints,
+        timeoutMs = 5000,
+        apiKey,
+    } = options;
