+
+/**
+ * Creates a `WatchFnClient` object compatible with the UI components.
+ *
+ * @example
+ * const client = createWatchFnClient({ baseUrl: "http://localhost:7100" });
+ * const metrics = await client.fetchMetrics({ timeRange: "PT1H" });
