+export function apifnWatchMiddleware(
+    options: WatchFnMiddlewareOptions
+): (req: unknown, res: unknown, next: (...args: unknown[]) => unknown) => Promise<void> {
+    const {
+        baseUrl,
+        apiKey,
+        fireAndForget = true,
