+
+// ─── Test spec ───────────────────────────────────────────────────────────────
+
+const TEST_SPEC: OpenAPIDocument = {
+    openapi: "3.1.0",
+    info: { title: "Mock Test API", version: "1.0.0" },
+    paths: {
+        "/users": {
+            get: {
+                summary: "List users",
+                responses: {
+                    "200": {
+                        description: "OK",
+                        content: {
+                            "application/json": {
+                                schema: {
+                                    type: "object",
+                                    properties: {
+                                        id: { type: "string" },
+                                        name: { type: "string" },
+                                        age: { type: "integer" },
+                                        active: { type: "boolean" },
+                                        tags: { type: "array", items: { type: "string" } },
+                                    },
+                                },
+                            },
+                        },
+                    },
+                },
+            },
+            post: {
+                summary: "Create user",
+                requestBody: {
+                    required: true,
+                    content: {
+                        "application/json": {
+                            schema: {
