+                                required: ["name"],
+                                properties: {
+                                    name: { type: "string" },
+                                    age: { type: "integer", minimum: 0 },
+                                },
+                            },
+                        },
+                    },
+                },
+                responses: {
+                    "201": {
+                        description: "Created",
+                        content: {
+                            "application/json": {
+                                example: { id: "abc-123", name: "Alice" },
+                            },
+                        },
+                    },
