+// ─── TV-MOCK-001: All paths served ───────────────────────────────────────────
+
+describe("TV-MOCK-001: all paths served", () => {
+    let mock = createMockServer({ spec: TEST_SPEC, port: 0 });
+
+    beforeAll(() => mock.start());
+    afterAll(() => mock.stop());
