+
+type MainTab = "docs" | "tryit" | "perf" | "history";
+
+export function ApiExplorer({ spec, theme = "auto", baseUrl, showHistory = true, watchfn, watchfnInterval = 10000, rateLimits, className }: ApiExplorerProps): React.ReactElement {
