+
+    // Theme injection
+    const themeStyle = useMemo(() => getThemeStyle(theme), [theme]);
+
+    return (
+        <div className={`apifn-root ${className ?? ""}`} style={s.root}>
+            <style>{themeStyle}</style>
+
+            {/* Top Bar */}
