+                        <div style={s.empty}>
+                            <div style={{ fontSize: "32px" }}>⚡</div>
+                            <div>Select an endpoint from the sidebar</div>
+                        </div>
+                    )}
+                </div>
+            </div>
+        </div>
+    );
+}

