+  const helper = {
+    get(name: string): string | undefined {
+      return env[name];
+    },
+    set(name: string, value: unknown): void {
+      env[name] = String(value);
+    },
+    unset(name: string): void {
+      delete env[name];
+    },
+    delete(name: string): void {
+      delete env[name];
+    },
+    all(): EnvStore {
+      return { ...env };
+    },
+  };
